package billing

import (
	"errors"
	"math"
	"strings"
	"testing"

	"github.com/tiktoken-go/tokenizer"
)

func countTotal(t *testing.T, c *TextCount) int64 {
	t.Helper()
	n, err := c.Total()
	if err != nil {
		t.Fatal(err)
	}
	return n
}

// Reference counts from OpenAI's cookbook, not generated by the Go implementation being tested:
// https://developers.openai.com/cookbook/examples/how_to_count_tokens_with_tiktoken (2026-10-20).
func TestTextCountReference(t *testing.T) {
	for _, tc := range []struct {
		text          string
		cl100k, o200k int64
	}{
		{"antidisestablishmentarianism", 6, 6},
		{"2 + 2 = 4", 7, 7},
		{"お誕生日おめでとう", 9, 8},
	} {
		for tok, want := range map[Tokenizer]int64{TokenizerCl100k: tc.cl100k, TokenizerO200k: tc.o200k} {
			t.Run(tc.text+"/"+string(rune('0'+tok)), func(t *testing.T) {
				t.Parallel() // independent counters share the same immutable vocabulary and regex
				c := NewTextCount(tok, math.MaxInt64)
				c.Add([]byte(tc.text))
				if got := countTotal(t, c); got != want {
					t.Fatalf("got %d, reference %d", got, want)
				}
			})
		}
	}
}

type failingCount struct {
	tokenizer.Codec
	err error
}

func (f failingCount) Count(string) (int, error) { return 0, f.err }

func TestTextCountDiscardsPartialFailure(t *testing.T) {
	t.Parallel()
	c := NewTextCount(TokenizerO200k, 1000)
	c.Add([]byte("hello"))
	want := errors.New("tokenizer failed")
	c.codec = failingCount{err: want}
	if c.Add([]byte("world")) || c.Add([]byte("again")) {
		t.Fatal("continued after a tokenizer failure")
	}
	if n, err := c.Total(); n != 0 || !errors.Is(err, want) {
		t.Fatalf("partial count was kept: %d, %v", n, err)
	}
}

// Limits include the smallest cap and the integer extreme; an exhausted counter must never consume another piece.
func TestTextCountBounds(t *testing.T) {
	t.Parallel()
	for _, tok := range []Tokenizer{TokenizerCl100k, TokenizerO200k, TokenizerClaude, TokenizerClaude47} {
		for _, text := range []string{"", "a", "🙂", "∑", "1", strings.Repeat("中文", 2000)} {
			for _, limit := range []int64{1, 2, 100, math.MaxInt64} {
				c := NewTextCount(tok, limit)
				more := c.Add([]byte(text))
				n := countTotal(t, c)
				if n < 0 || n > min(limit, int64(len(text))) || more != (n < limit) {
					t.Fatalf("tokenizer %d, bytes %d, limit %d: total %d, more %v", tok, len(text), limit, n, more)
				}
			}
		}
	}
}
